/* ---- Download button next to "Welcome to": shown until the app is installed ---- */
var DEFER_PROMPT=null;
function isStandalone(){return (window.matchMedia&&matchMedia("(display-mode: standalone)").matches)||navigator.standalone===true}
function dlState(){
  var b=$("dlb");if(!b)return;
  if(window.__kalInstalled){DEFER_PROMPT=null;wr("store.installed",true)}
  if(window.__kalPrompt&&!DEFER_PROMPT)DEFER_PROMPT=window.__kalPrompt;
  // Chrome only offers to install an app that is NOT installed, so an offer overrides an old "installed" flag
  if(DEFER_PROMPT&&rd("store.installed",false)===true)wr("store.installed",false);
  b.hidden=isStandalone()||(!DEFER_PROMPT&&rd("store.installed",false)===true);
}
function dlClick(){
  if(DEFER_PROMPT){var e=DEFER_PROMPT;DEFER_PROMPT=null;window.__kalPrompt=null;e.prompt();if(e.userChoice)e.userChoice.then(function(c){if(c&&c.outcome==="accepted")wr("store.installed",true);dlState()});return}
  showInstallHelp()
}
function showInstallHelp(){
  var old=document.getElementById("ikm");if(old)old.remove();
  var st=window.kalInstallSteps?window.kalInstallSteps():["Open your browser menu and choose 'Install app' or 'Add to Home Screen'."];
  var m=document.createElement("div");m.id="ikm";m.className="ikm";m.setAttribute("role","dialog");m.setAttribute("aria-modal","true");
  var c=document.createElement("div");c.className="ikc";
  var h=document.createElement("h3");h.textContent="Install KALIMAT";c.appendChild(h);
  var p=document.createElement("p");p.textContent="Add this shop to your phone like an app.";c.appendChild(p);
  var ol=document.createElement("ol");st.forEach(function(s){var li=document.createElement("li");li.textContent=s;ol.appendChild(li)});c.appendChild(ol);
  var b=document.createElement("button");b.type="button";b.className="btn";b.textContent="Got it";b.onclick=function(){m.remove()};c.appendChild(b);
  m.appendChild(c);m.addEventListener("click",function(ev){if(ev.target===m)m.remove()});document.body.appendChild(m)
}
